using System;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports.Editor;
namespace LWS.TruckBowling.Editor {
public static class BowlingWheelAudit {
 public static void Run(){EditorSceneManager.OpenScene(BowlingAuthoring.Scene);var report=new StringBuilder("Read-only saved Bowling exterior / wheel / venue audit\n");foreach(var lane in UnityEngine.Object.FindObjectsByType<BowlingLane>()){report.AppendLine("LANE "+lane.index+" exterior="+lane.truck.exterior.name+" meshCount="+lane.truck.GetComponentsInChildren<MeshFilter>(true).Length);foreach(var w in lane.truck.wheels)report.AppendLine("NWH "+w.name+" local="+lane.truck.transform.InverseTransformPoint(w.transform.position)+" radius="+w.wheel.radius+" rotating="+(w.wheel.rotatingContainer!=null));foreach(var f in lane.truck.GetComponentsInChildren<MeshFilter>(true)){if(f.name.Contains("Whl")||f.name.Contains("Wheel"))report.AppendLine("VISUAL "+f.name+" enabled="+f.GetComponent<Renderer>().enabled+" active="+f.gameObject.activeInHierarchy+" localBounds="+SportsRallyAuthoring.BoundsIn(f,lane.truck.transform)+" meshCenter="+f.sharedMesh.bounds.center);}report.AppendLine("Sweep="+lane.sweep.position+" bounds="+lane.sweep.GetComponent<Renderer>().bounds);}
 foreach(var root in EditorSceneManager.GetActiveScene().GetRootGameObjects())report.AppendLine("ROOT "+root.name+" active="+root.activeSelf+" renderers="+root.GetComponentsInChildren<Renderer>(true).Count(r=>r.enabled&&r.gameObject.activeInHierarchy)+" contacts="+root.GetComponentsInChildren<Collider>(true).Count(c=>c.enabled&&c.gameObject.activeInHierarchy));System.IO.File.WriteAllText("Logs/TruckSports/EssentialRelease/bowling-wheel-venue-baseline.txt",report.ToString());}
}
}
